import { expect, test } from "bun:test";
import { makePlan, parseTasks } from "./cli";

test("plans deterministic parallel work and a lexicographic critical path", () => {
  const plan = makePlan(parseTasks({ tasks: [
    { id: "deploy", duration: 1, dependsOn: ["build", "docs"] },
    { id: "docs", duration: 3 },
    { id: "lint", duration: 1 },
    { id: "build", duration: 2, dependsOn: ["lint"] },
  ] }));
  expect(plan).toEqual({
    order: ["docs", "lint", "build", "deploy"],
    layers: [["docs", "lint"], ["build"], ["deploy"]],
    earliest: { docs: { start: 0, finish: 3 }, lint: { start: 0, finish: 1 }, build: { start: 1, finish: 3 }, deploy: { start: 3, finish: 4 } },
    totalDuration: 4,
    criticalPath: ["docs", "deploy"],
  });
});

test("supports empty and zero-duration inputs", () => {
  expect(makePlan(parseTasks({ tasks: [] }))).toEqual({ order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [] });
  expect(makePlan(parseTasks({ tasks: [{ id: "a", duration: 0 }, { id: "b", duration: 0, dependsOn: ["a"] }] })).criticalPath).toEqual(["a", "b"]);
});

test("rejects unknown dependencies and reports deterministic cycles", () => {
  expect(() => parseTasks({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] })).toThrow("unknown dependency 'missing'");
  expect(() => makePlan(parseTasks({ tasks: [{ id: "b", duration: 1, dependsOn: ["a"] }, { id: "a", duration: 1, dependsOn: ["b"] }] }))).toThrow("a -> b -> a");
});

type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function fail(message: string): never {
  throw new Error(message);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseTasks(value: unknown): Task[] {
  if (!isPlainObject(value) || !Array.isArray(value.tasks)) {
    fail("Invalid input: 'tasks' must be an array.");
  }

  const tasks: Task[] = [];
  const ids = new Set<string>();
  for (let index = 0; index < value.tasks.length; index++) {
    const raw = value.tasks[index];
    const prefix = `Invalid task at index ${index}:`;
    if (!isPlainObject(raw)) fail(`${prefix} must be an object.`);
    if (typeof raw.id !== "string" || raw.id.length === 0) {
      fail(`${prefix} 'id' must be a non-empty string.`);
    }
    if (ids.has(raw.id)) fail(`Invalid input: duplicate task id '${raw.id}'.`);
    if (typeof raw.duration !== "number" || !Number.isFinite(raw.duration) || raw.duration < 0) {
      fail(`${prefix} 'duration' must be a finite non-negative number.`);
    }

    const dependsOn = raw.dependsOn === undefined ? [] : raw.dependsOn;
    if (!Array.isArray(dependsOn) || dependsOn.some((id) => typeof id !== "string")) {
      fail(`${prefix} 'dependsOn' must be an array of strings.`);
    }
    if (new Set(dependsOn).size !== dependsOn.length) {
      fail(`${prefix} 'dependsOn' must not contain duplicates.`);
    }
    if (dependsOn.includes(raw.id)) fail(`${prefix} cannot depend on itself.`);

    ids.add(raw.id);
    tasks.push({ id: raw.id, duration: raw.duration, dependsOn: [...dependsOn] });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) {
        fail(`Invalid task '${task.id}': unknown dependency '${dependency}'.`);
      }
    }
  }
  return tasks;
}

function compareSequences(left: string[], right: string[]): number {
  for (let index = 0; index < Math.min(left.length, right.length); index++) {
    const comparison = left[index].localeCompare(right[index]);
    if (comparison !== 0) return comparison;
  }
  return left.length - right.length;
}

function findCycle(tasks: Task[]): string[] | undefined {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];

  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dependency) === 1) {
        return [...stack.slice(stack.indexOf(dependency)), dependency];
      }
      if (state.get(dependency) !== 2) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  };

  for (const id of [...byId.keys()].sort()) {
    if (!state.get(id)) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

