    taskLayer.set(id, layer);
    paths.set(id, path);
    (layers[layer] ??= []).push(id);
  }
  for (const layer of layers) layer.sort();

  let totalDuration = 0;
  let criticalPath: string[] = [];
  for (const id of order) {
    const finish = earliest[id].finish;
    const path = paths.get(id)!;
    if (finish > totalDuration || (finish === totalDuration && compareSequences(path, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = path;
    }
  }
  return { order, layers, earliest, totalDuration, criticalPath };
}

export function main(arguments_: string[], readFile: (path: string) => string = (path) => Bun.file(path).text() as unknown as string): void {
